{
  "lines": [
    {
      "key": "opening",
      "japanese": "あれ、〇〇さん？",
      "reading": "あれ、まるまるさん？",
      "romaji": "Are, marumaru-san? (Oh, [Name]-san?) - *Replace 〇〇 with the person's name.*"
    },
    {
      "key": "reply",
      "japanese": "あ、〇〇さん！こんにちは。",
      "reading": "あ、まるまるさん！こんにちは。",
      "romaji": "A, marumaru-san! Konnichiwa. (Oh, [Name]-san! Hello.)"
    },
    {
      "key": "inquiry",
      "japanese": "今、忙しい？",
      "reading": "いま、いそがしい？",
      "romaji": "Ima, isogashii? (Are you busy now?)"
    },
    {
      "key": "response_positive",
      "japanese": "ううん、大丈夫。ちょっと暇なんだ。",
      "reading": "ううん、だいじょうぶ。ちょっとひまなんだ。",
      "romaji": "Uun, daijoubu. Chotto hima nan da. (No, I'm okay. I have some free time.)"
    },
    {
      "key": "suggestion",
      "japanese": "どっかで一杯どう？",
      "reading": "どっかでいっぱいどう？",
      "romaji": "Dokka de ippai dou? (How about a drink somewhere?)"
    }
  ]
}

